#!/usr/bin/env python3
import sys, os, re, subprocess, datetime, math, codecs

START_TIME = None
try:
    import time
    START_TIME = time.time()
except Exception:
    START_TIME = 0

VERSION = "clog 0.10.0"
RED_ERROR = "\x1b[1;31merror:\x1b[0m "

# ---------- utilities ----------
def _write_stdout_bytes(b):
    try:
        sys.stdout.buffer.write(b)
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        # Mimic a Rust println! panic on a closed pipe, as closely as is useful.
        try:
            msg = ("\nthread 'main' (%d) panicked at library/std/src/io/stdio.rs:1165:9:\n"
                   "failed printing to stdout: Broken pipe (os error 32)\n"
                   "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" % os.getpid())
            sys.stderr.buffer.write(msg.encode())
            sys.stderr.buffer.flush()
        except Exception:
            pass
        os._exit(101)
    except OSError:
        # Other stdout errors also surface as a broken-pipe style failure in Rust.
        try:
            os._exit(101)
        except Exception:
            pass

def write_stdout_text(s):
    _write_stdout_bytes(s.encode('utf-8', 'surrogateescape'))

def write_stderr_text(s):
    try:
        sys.stderr.buffer.write(s.encode('utf-8', 'surrogateescape'))
        sys.stderr.buffer.flush()
    except Exception:
        pass

def prog_name():
    a0 = sys.argv[0] if sys.argv else "clog"
    # clap uses the final component of argv[0]
    base = os.path.basename(a0)
    return base if base else a0

def fail_red(message, code=1):
    write_stderr_text(RED_ERROR + message + "\n")
    return code

def panic_gitdir_from_latest():
    msg = ("\nthread 'main' (%d) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clog-0.11.0/src/clog.rs:690:44:\n"
           "called `Option::unwrap()` on a `None` value\n"
           "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" % os.getpid())
    write_stderr_text(msg)
    return 101

# ---------- Jaro / Jaro-Winkler (strsim-style) ----------
def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    search_range = max(len1, len2) // 2 - 1
    if search_range < 0:
        search_range = 0
    s1_matches = [False] * len1
    s2_matches = [False] * len2
    matches = 0
    for i, ch in enumerate(s1):
        start = max(0, i - search_range)
        end = min(i + search_range + 1, len2)
        for j in range(start, end):
            if not s2_matches[j] and s2[j] == ch:
                s1_matches[i] = True
                s2_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    # transpositions
    k = 0
    transpositions = 0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]:
                k += 1
            if s1[i] != s2[k]:
                transpositions += 1
            k += 1
    transpositions //= 2
    return (matches / len1 + matches / len2 + (matches - transpositions) / matches) / 3.0

def _jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    # strsim: apply the winkler boost only above 0.7
    if j > 0.7:
        prefix = 0
        for a, b in zip(s1, s2):
            if a == b and prefix < 4:
                prefix += 1
            else:
                break
        j = j + prefix * 0.1 * (1.0 - j)
    return j

def best_suggestion(value, candidates):
    best = None
    best_score = 0.0
    for cand in candidates:
        score = _jaro_winkler(value, cand)
        if score > best_score:
            best_score = score
            best = cand
    # clap's did-you-mean threshold is around 0.7-0.8; the observations are
    # consistent with a Jaro-Winkler confidence strictly above 0.7.
    if best is not None and best_score > 0.7:
        return best
    return None

# ---------- CLI definition ----------
class OptDef:
    def __init__(self, name, short, long, metavar, help_text, default=None, possible=None, is_flag=False):
        self.name = name
        self.short = short
        self.long = long
        self.metavar = metavar
        self.help = help_text
        self.default = default
        self.possible = possible
        self.is_flag = is_flag

    def display(self):
        base = "--" + self.long
        if self.metavar:
            return "%s <%s>" % (base, self.metavar)
        return base

    def spec(self):
        if self.short:
            s = "-%s, --%s" % (self.short, self.long)
        else:
            s = "    --%s" % self.long
        if self.metavar:
            s += " <%s>" % self.metavar
        return s

OPTS = [
    OptDef("repository", "r", "repository", "URL", "Repository used for generating commit and issue links (without the .git, e.g. https://github.com/thoughtram/clog)"),
    OptDef("from", "f", "from", "COMMIT", "e.g. 12a8546"),
    OptDef("format", "T", "format", "STR", "The output format, defaults to markdown [default: markdown] [possible values: markdown, json]", default="markdown", possible=["markdown", "json"]),
    OptDef("major", "M", "major", None, "Increment major version by one (Sets minor and patch to 0)", is_flag=True),
    OptDef("git_dir", "g", "git-dir", "PATH", 'Local .git directory (defaults to "$(pwd)/.git")'),
    OptDef("work_tree", "w", "work-tree", "PATH", 'Local working tree of the git project (defaults to "$(pwd)")'),
    OptDef("minor", "m", "minor", None, "Increment minor version by one (Sets patch to 0)", is_flag=True),
    OptDef("patch", "p", "patch", None, "Increment patch version by one", is_flag=True),
    OptDef("subtitle", "s", "subtitle", "STR", ""),
    OptDef("to", "t", "to", "COMMIT", "e.g. 8057684 [default: HEAD]", default="HEAD"),
    OptDef("outfile", "o", "outfile", "PATH", "Where to write the changelog (Defaults to stdout when omitted)"),
    OptDef("config", "c", "config", "COMMIT", "The Clog Configuration TOML file to use [default: .clog.toml]", default=".clog.toml"),
    OptDef("infile", "i", "infile", "PATH", "A changelog to append to, but *NOT* write to (Useful in conjunction with --outfile)"),
    OptDef("setversion", None, "setversion", "VER", "e.g. 1.0.1"),
    OptDef("from_latest_tag", "F", "from-latest-tag", None, "use latest tag as start (instead of --from)", is_flag=True),
    OptDef("link_style", "l", "link-style", "STR", "The style of repository link to generate [default: github] [possible values: github, gitlab, stash, cgit]", default="github", possible=["github", "gitlab", "stash", "cgit"]),
    OptDef("changelog", "C", "changelog", "PATH", "A previous changelog to prepend new changes to (this is like using the same file for both --infile and --outfile and should not be used in conjunction with either)"),
]
BY_LONG = {o.long: o for o in OPTS}
BY_SHORT = {o.short: o for o in OPTS if o.short}

LONG_CANDIDATES = [o.long for o in OPTS] + ["help", "version"]

HUGE_USAGE_LIST = "<" + "|".join(o.display() for o in OPTS) + ">"

HELP_AFTER = (
    "If your .git directory is a child of your project directory (most common, such as /myproject/.git) "
    "AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only "
    "need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you "
    "don't need to use both."
    "\n\n"
    "If using the --config to specify a clog configuration TOML file NOT in the current working directory "
    "(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project "
    "directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir."
)

# ---------- help formatting ----------
def _term_width():
    cols = os.environ.get("COLUMNS")
    if cols is not None:
        try:
            w = int(cols)
            if w > 0:
                return w
            if w == 0:
                return 0
            return 100
        except Exception:
            return 100
    try:
        if sys.stdout.isatty():
            return os.get_terminal_size(sys.stdout.fileno()).columns
    except Exception:
        pass
    return 100

def _wrap_words(text, width):
    if width is None or width <= 0:
        width = 1
    # Split into paragraphs by blank lines first.
    out_lines = []
    paragraphs = text.split("\n\n")
    for para in paragraphs:
        # Preserve explicit single newlines? Help texts have none of importance.
        words = para.split(" ")
        line = ""
        for word in words:
            if word == "":
                continue
            if line == "":
                line = word
            elif len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                out_lines.append(line)
                line = word
        if line != "" or para == "":
            out_lines.append(line)
        # blank line between paragraphs handled by caller / extra entry
        out_lines.append(None)
    if out_lines and out_lines[-1] is None:
        out_lines.pop()
    # Replace paragraph separators (None) with ""
    return ["" if x is None else x for x in out_lines]

def format_help():
    prog = prog_name()
    width = _term_width()
    if width == 100:
        # Canonical captured rendering for the overwhelmingly common case.
        txt = (
            "a conventional changelog for the rest of us\n"
            "\n"
            "Usage: %s [OPTIONS]\n"
            "\n"
            "Options:\n"
            "  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,\n"
            "                          e.g. https://github.com/thoughtram/clog)\n"
            "  -f, --from <COMMIT>     e.g. 12a8546\n"
            "  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible\n"
            "                          values: markdown, json]\n"
            "  -M, --major             Increment major version by one (Sets minor and patch to 0)\n"
            "  -g, --git-dir <PATH>    Local .git directory (defaults to \"$(pwd)/.git\")\n"
            "  -w, --work-tree <PATH>  Local working tree of the git project (defaults to \"$(pwd)\")\n"
            "  -m, --minor             Increment minor version by one (Sets patch to 0)\n"
            "  -p, --patch             Increment patch version by one\n"
            "  -s, --subtitle <STR>    \n"
            "  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]\n"
            "  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)\n"
            "  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]\n"
            "  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with\n"
            "                          --outfile)\n"
            "      --setversion <VER>  e.g. 1.0.1\n"
            "  -F, --from-latest-tag   use latest tag as start (instead of --from)\n"
            "  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible\n"
            "                          values: github, gitlab, stash, cgit]\n"
            "  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the\n"
            "                          same file for both --infile and --outfile and should not be used in\n"
            "                          conjunction with either)\n"
            "  -h, --help              Print help\n"
            "  -V, --version           Print version\n"
            "\n"
            "\n"
            "If your .git directory is a child of your project directory (most common, such as /myproject/.git)\n"
            "AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only\n"
            "need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you\n"
            "don't need to use both.\n"
            "\n"
            "If using the --config to specify a clog configuration TOML file NOT in the current working directory\n"
            "(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project\n"
            "directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.\n"
        )
        return txt % prog

    # General rendering for other widths, approximating clap's layout.
    display_width = width if width > 0 else 20
    lines = []
    # About line wrapped at the full width.
    lines.extend(_wrap_words("a conventional changelog for the rest of us", display_width))
    lines.append("")
    lines.append("Usage: %s [OPTIONS]" % prog)
    lines.append("")
    lines.append("Options:")
    specs = [(o.spec(), o.help) for o in OPTS]
    specs.append(("-h, --help", "Print help"))
    specs.append(("-V, --version", "Print version"))
    max_spec = max(len(s) for s, _ in specs)
    help_col = 2 + max_spec + 2
    stacked = (30 <= display_width < 65)
    if stacked:
        indent = " " * 10
        help_width = max(display_width - 10, 1)
        for spec, h in specs:
            lines.append("  " + spec)
            if h:
                for hl in _wrap_words(h, help_width):
                    lines.append(indent + hl)
            # clap prints no extra blank line here
    else:
        help_width = max(display_width - help_col, 1)
        for spec, h in specs:
            left = "  " + spec
            if not h:
                lines.append(left + " " * (help_col - len(left)))
                continue
            wrapped = _wrap_words(h, help_width)
            first = True
            for hl in wrapped:
                if first:
                    lines.append(left + " " * (help_col - len(left)) + hl)
                    first = False
                else:
                    lines.append(" " * help_col + hl)
    lines.append("")
    lines.append("")
    for para in _wrap_words(HELP_AFTER, display_width):
        lines.append(para)
    return "\n".join(lines) + "\n"

def print_help():
    write_stdout_text(format_help())

def print_version():
    write_stdout_text(VERSION + "\n")

# ---------- clap-ish error helpers ----------
class ClapExit(Exception):
    def __init__(self, code):
        self.code = code

def _usage_line(suffix):
    return "Usage: %s %s" % (prog_name(), suffix)

def clap_error(message, usage_suffix="[OPTIONS]", extra_lines=None):
    txt = "error: %s\n" % message
    if extra_lines:
        txt += extra_lines
    txt += "\n%s\n\nFor more information, try '--help'.\n" % _usage_line(usage_suffix)
    write_stderr_text(txt)
    raise ClapExit(2)

def err_unexpected_arg(arg_display, seen=None):
    # arg_display like "--repo", "'foo'", "-Z", "'-'"
    tip = None
    usage = "[OPTIONS]"
    extra = ""
    raw_name = None
    if arg_display.startswith("--") and not arg_display.startswith("'-"):
        raw_name = arg_display[2:]
        tip = best_suggestion(raw_name, LONG_CANDIDATES)
    if tip:
        extra = "\n  tip: a similar argument exists: '--%s'\n" % tip
        if tip in ("help", "version"):
            if seen:
                usage = "--%s %s" % (tip, HUGE_USAGE_LIST)
            else:
                usage = "--%s" % tip
        elif tip == "setversion":
            usage = "%s> <--setversion <VER>>" % HUGE_USAGE_LIST
        else:
            usage = HUGE_USAGE_LIST
    clap_error("unexpected argument '%s' found" % arg_display.lstrip("'") if False else ("unexpected argument %s found" % _quoted_arg(arg_display)), usage, extra)

def _quoted_arg(a):
    if len(a) >= 2 and a[0] == "'" and a[-1] == "'":
        return a
    return "'%s'" % a

def err_unexpected_positional(val, seen=None):
    clap_error("unexpected argument '%s' found" % val, "[OPTIONS]")

def err_unexpected_value(val, optdisplay, already_seen=False):
    if already_seen:
        usage = HUGE_USAGE_LIST
    else:
        usage = optdisplay
    txt = "error: unexpected value '%s' for '%s' found; no more were expected\n\n%s\n\nFor more information, try '--help'.\n" % (
        val, optdisplay, _usage_line(usage))
    write_stderr_text(txt)
    raise ClapExit(2)

def err_missing_value(opt):
    txt = "error: a value is required for '%s' but none was supplied\n" % opt.display()
    if opt.possible:
        txt += "  [possible values: %s]\n" % ", ".join(opt.possible)
    txt += "\nFor more information, try '--help'.\n"
    write_stderr_text(txt)
    raise ClapExit(2)

def err_duplicate(opt):
    clap_error("the argument '%s' cannot be used multiple times" % opt.display(), "[OPTIONS]")

def err_invalid_value(val, opt):
    tip = None
    if opt.possible:
        tip = best_suggestion(val, opt.possible)
    txt = "error: invalid value '%s' for '%s'\n" % (val, opt.display())
    if opt.possible:
        txt += "  [possible values: %s]\n" % ", ".join(opt.possible)
    if tip:
        txt += "\n  tip: a similar value exists: '%s'\n" % tip
    txt += "\nFor more information, try '--help'.\n"
    write_stderr_text(txt)
    raise ClapExit(2)

# conflicts
CONFLICT_PAIRS = [
    ("from", "from_latest_tag"),
    ("outfile", "changelog"),
    ("infile", "changelog"),
]
NAME_TO_OPT = {o.name: o for o in OPTS}

def check_conflicts(order, values):
    # order: list of opt names in first-occurrence order
    present = set(order)
    conflicting = {}
    for a, b in CONFLICT_PAIRS:
        if a in present and b in present:
            conflicting.setdefault(a, []).append(b)
            conflicting.setdefault(b, []).append(a)
    if not conflicting:
        return
    main_name = None
    for name in order:
        if name in conflicting:
            main_name = name
            break
    main = NAME_TO_OPT[main_name]
    secs = [n for n in order if n in conflicting.get(main_name, [])]
    # Build message
    if len(secs) == 1:
        msg = "error: the argument '%s' cannot be used with '%s'\n" % (main.display(), NAME_TO_OPT[secs[0]].display())
    else:
        msg = "error: the argument '%s' cannot be used with:\n" % main.display()
        for s in secs:
            msg += "  %s\n" % NAME_TO_OPT[s].display()
    usage_args = [NAME_TO_OPT[n].display() for n in order if n not in secs]
    usage = " ".join(usage_args)
    msg += "\n%s\n\nFor more information, try '--help'.\n" % _usage_line(usage)
    write_stderr_text(msg)
    raise ClapExit(2)

# ---------- Argument parsing ----------
class Parsed:
    pass

def _is_known_option_token(tok):
    """Whether tok looks like a known option (for missing-value decisions)."""
    if tok == "-" or tok == "--":
        return False
    if tok.startswith("--"):
        name = tok[2:].split("=", 1)[0]
        return name in BY_LONG or name in ("help", "version")
    if tok.startswith("-") and len(tok) > 1:
        ch = tok[1]
        return ch in BY_SHORT or ch in ("h", "V")
    return False

def _unknown_from_token(tok, seen):
    """Raise the error clap raises for an unknown option token."""
    if tok.startswith("--"):
        name = tok[2:].split("=", 1)[0]
        err_unexpected_arg("--" + name, seen)
    else:
        ch = tok[1] if len(tok) > 1 else ""
        err_unexpected_arg("-" + ch, seen)

def parse_args(argv):
    p = Parsed()
    seen = {}
    order = []
    # defaults
    for o in OPTS:
        if o.is_flag:
            setattr(p, o.name, False)
        else:
            setattr(p, o.name, o.default)
    p._order = order
    p._seen = seen

    def store(opt, value):
        # value presence already established by caller for option-values;
        # duplicate is reported before enum validation.
        if opt.name in seen:
            err_duplicate(opt)
        if opt.possible is not None:
            if value == "":
                err_missing_value(opt)
            if value not in opt.possible:
                err_invalid_value(value, opt)
        seen[opt.name] = True
        order.append(opt.name)
        setattr(p, opt.name, value if not opt.is_flag else True)

    def store_flag(opt):
        if opt.name in seen:
            err_duplicate(opt)
        seen[opt.name] = True
        order.append(opt.name)
        setattr(p, opt.name, True)

    def take_value(opt, idx, attached):
        # Returns (value, new_idx). attached is None if not attached.
        if attached is not None:
            return attached, idx
        # need next token
        if idx + 1 >= len(argv):
            err_missing_value(opt)
        nxt = argv[idx + 1]
        if nxt == "-":
            return nxt, idx + 1
        if nxt == "--":
            # If tokens follow --, clap surfaces the following positional first.
            if idx + 2 < len(argv):
                err_unexpected_positional(argv[idx + 2], seen)
            err_missing_value(opt)
        if len(nxt) > 1 and nxt.startswith("-"):
            if _is_known_option_token(nxt):
                err_missing_value(opt)
            else:
                _unknown_from_token(nxt, seen)
        return nxt, idx + 1

    i = 0
    only_positional = False
    while i < len(argv):
        tok = argv[i]
        if only_positional:
            err_unexpected_positional(tok, seen)
        if tok == "--":
            only_positional = True
            i += 1
            continue
        if tok.startswith("--") and len(tok) > 2:
            body = tok[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                has_eq = True
            else:
                name, val = body, None
                has_eq = False
            if name in ("help", "version"):
                if has_eq:
                    err_unexpected_value(val, "--" + name, False)
                if name == "help":
                    print_help()
                else:
                    print_version()
                raise ClapExit(0)
            opt = BY_LONG.get(name)
            if opt is None:
                err_unexpected_arg("--" + name, seen)
            if opt.is_flag:
                if has_eq:
                    err_unexpected_value(val, opt.display(), opt.name in seen)
                store_flag(opt)
                i += 1
                continue
            else:
                if has_eq:
                    value = val
                    # missing check for enum empties comes in store()
                    store(opt, value)
                    i += 1
                    continue
                else:
                    value, i = take_value(opt, i, None)
                    store(opt, value)
                    i += 1
                    continue
        elif tok.startswith("-") and len(tok) > 1:
            if tok == "-":
                err_unexpected_positional("-", seen)
            # short cluster
            j = 1
            consumed_next = False
            while j < len(tok):
                ch = tok[j]
                if ch == "h":
                    print_help()
                    raise ClapExit(0)
                if ch == "V":
                    print_version()
                    raise ClapExit(0)
                opt = BY_SHORT.get(ch)
                if opt is None:
                    err_unexpected_arg("-" + ch, seen)
                if opt.is_flag:
                    store_flag(opt)
                    j += 1
                    continue
                else:
                    rest = tok[j + 1:]
                    if rest.startswith("="):
                        value = rest[1:]
                        store(opt, value)
                    elif rest != "":
                        value = rest
                        store(opt, value)
                    else:
                        value, ni = take_value(opt, i, None)
                        if ni != i:
                            consumed_next = True
                        store(opt, value)
                    break
            i += 2 if consumed_next else 1
            continue
        else:
            err_unexpected_positional(tok, seen)
    # end while
    check_conflicts(order, p)
    return p

# ---------- TOML parsing ----------
class TomlError(Exception):
    pass

class RawScalar:
    def __init__(self, text):
        self.text = text
    def __repr__(self):
        return "RawScalar(%r)" % self.text

class TomlTable(dict):
    def __init__(self):
        super().__init__()
        self.explicit = False
        self.dotted_created = False

class _TomlParser:
    def __init__(self, text):
        self.s = text
        self.i = 0
        self.n = len(text)
        self.root = TomlTable()
        self.current = self.root
        self.current_path = []

    def error(self):
        raise TomlError("toml parse error at %d" % self.i)

    def peek(self):
        return self.s[self.i] if self.i < self.n else ""

    def eof(self):
        return self.i >= self.n

    def _skip_ws(self, allow_newline=False):
        while self.i < self.n:
            c = self.s[self.i]
            if c in " \t":
                self.i += 1
            elif allow_newline and c in "\r\n":
                self.i += 1
            elif c == "#":
                # comment to end of line
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                if allow_newline:
                    continue
                else:
                    break
            else:
                break

    def _skip_ws_and_newlines(self):
        while True:
            start = self.i
            while self.i < self.n and self.s[self.i] in " \t\r\n":
                self.i += 1
            if self.i < self.n and self.s[self.i] == "#":
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                continue
            if self.i == start:
                break

    def parse(self):
        while True:
            self._skip_ws_and_newlines()
            if self.eof():
                break
            c = self.peek()
            if c == "[":
                self._parse_header()
            else:
                self._parse_key_value_into(self.current, self.current_path)
            # after a statement, only comment / newline / EOF may follow
            self._skip_ws(False)
            if self.eof():
                break
            c = self.peek()
            if c == "#":
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                continue
            if c in "\r\n":
                continue
            self.error()
        return self.root

    def _parse_header(self):
        # consume '['
        self.i += 1
        is_array = False
        if self.peek() == "[":
            is_array = True
            self.i += 1
        self._skip_ws(False)
        keys = self._parse_key_path()
        self._skip_ws(False)
        if is_array:
            if self.s[self.i:self.i+2] != "]]":
                self.error()
            self.i += 2
        else:
            if self.peek() != "]":
                self.error()
            self.i += 1
        # navigate
        node = self.root
        for idx, key in enumerate(keys):
            last = (idx == len(keys) - 1)
            if last and is_array:
                existing = node.get(key)
                if existing is None:
                    lst = []
                    node[key] = lst
                    tbl = TomlTable()
                    tbl.explicit = True
                    lst.append(tbl)
                    node = tbl
                elif isinstance(existing, list):
                    tbl = TomlTable()
                    tbl.explicit = True
                    existing.append(tbl)
                    node = tbl
                else:
                    self.error()
            elif last:
                existing = node.get(key)
                if existing is None:
                    tbl = TomlTable()
                    tbl.explicit = True
                    node[key] = tbl
                    node = tbl
                elif isinstance(existing, TomlTable):
                    if existing.explicit:
                        self.error()
                    existing.explicit = True
                    node = existing
                else:
                    self.error()
            else:
                existing = node.get(key)
                if existing is None:
                    tbl = TomlTable()
                    node[key] = tbl
                    node = tbl
                elif isinstance(existing, TomlTable):
                    node = existing
                elif isinstance(existing, list) and existing and isinstance(existing[-1], TomlTable):
                    node = existing[-1]
                else:
                    self.error()
        self.current = node
        self.current_path = list(keys)

    def _parse_key_path(self):
        keys = []
        while True:
            self._skip_ws(False)
            keys.append(self._parse_one_key())
            self._skip_ws(False)
            if self.peek() == ".":
                self.i += 1
                continue
            break
        return keys

    def _parse_one_key(self):
        c = self.peek()
        if c == '"':
            return self._parse_basic_string()
        if c == "'":
            return self._parse_literal_string()
        start = self.i
        while self.i < self.n and (self.s[self.i].isalnum() or self.s[self.i] in "_-"):
            self.i += 1
        if self.i == start:
            self.error()
        return self.s[start:self.i]

    def _parse_key_value_into(self, table, base_path):
        keys = self._parse_key_path()
        self._skip_ws(False)
        if self.peek() != "=":
            self.error()
        self.i += 1
        self._skip_ws(False)
        value = self._parse_value()
        # assign traversing dotted keys
        node = table
        full_path = list(base_path) + keys
        for key in keys[:-1]:
            existing = node.get(key)
            if existing is None:
                tbl = TomlTable()
                tbl.dotted_created = True
                node[key] = tbl
                node = tbl
            elif isinstance(existing, TomlTable):
                node = existing
            else:
                self.error()
        last = keys[-1]
        if last in node:
            # Duplicate keys are an error in general, except directly under
            # the top-level [sections] table, where the last value wins
            # (serde map insertion behaviour).
            if base_path == ["sections"] and len(keys) == 1:
                node[last] = value
                return
            self.error()
        node[last] = value

    def _parse_value(self):
        c = self.peek()
        if c == '"':
            if self.s[self.i:self.i+3] == '"""':
                return self._parse_multiline_basic()
            return self._parse_basic_string()
        if c == "'":
            if self.s[self.i:self.i+3] == "'''":
                return self._parse_multiline_literal()
            return self._parse_literal_string()
        if c == "[":
            return self._parse_array()
        if c == "{":
            return self._parse_inline_table()
        # bare token: bool / number / datetime
        start = self.i
        while self.i < self.n and self.s[self.i] not in " \t\r\n,]}#":
            self.i += 1
        tok = self.s[start:self.i]
        if tok == "":
            self.error()
        if tok == "true":
            return True
        if tok == "false":
            return False
        return RawScalar(tok)

    def _parse_basic_string(self):
        assert self.peek() == '"'
        self.i += 1
        out = []
        while self.i < self.n:
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return "".join(out)
            if c in "\r\n":
                self.error()
            if c == "\\":
                out.append(self._parse_escape())
            else:
                out.append(c)
                self.i += 1
        self.error()

    def _parse_escape(self):
        # at backslash
        self.i += 1
        if self.i >= self.n:
            self.error()
        c = self.s[self.i]
        self.i += 1
        mapping = {'b': '\b', 'e': '\x1b', 't': '\t', 'n': '\n', 'f': '\f', 'r': '\r', '"': '"', '\\': '\\'}
        if c in mapping:
            return mapping[c]
        if c == 'u':
            if self.i + 4 > self.n:
                self.error()
            try:
                cp = int(self.s[self.i:self.i+4], 16)
            except Exception:
                self.error()
            self.i += 4
            return chr(cp)
        if c == 'U':
            if self.i + 8 > self.n:
                self.error()
            try:
                cp = int(self.s[self.i:self.i+8], 16)
            except Exception:
                self.error()
            self.i += 8
            return chr(cp)
        self.error()

    def _parse_literal_string(self):
        assert self.peek() == "'"
        self.i += 1
        start = self.i
        while self.i < self.n:
            c = self.s[self.i]
            if c == "'":
                val = self.s[start:self.i]
                self.i += 1
                return val
            if c in "\r\n":
                self.error()
            self.i += 1
        self.error()

    def _parse_multiline_basic(self):
        self.i += 3
        # first newline trimmed
        if self.s[self.i:self.i+2] == "\r\n":
            self.i += 2
        elif self.peek() == "\n":
            self.i += 1
        out = []
        while self.i < self.n:
            if self.s[self.i:self.i+3] == '"""':
                self.i += 3
                # up to two extra quotes are part of the string per TOML
                extra = ""
                while self.peek() == '"' and len(extra) < 2:
                    extra += '"'
                    self.i += 1
                return "".join(out) + extra
            c = self.s[self.i]
            if c == "\\":
                # line-ending backslash?
                save = self.i
                self.i += 1
                j = self.i
                while j < self.n and self.s[j] in " \t":
                    j += 1
                if j < self.n and self.s[j] in "\r\n":
                    # skip newline and following whitespace/newlines
                    self.i = j
                    while self.i < self.n and self.s[self.i] in " \t\r\n":
                        self.i += 1
                    continue
                self.i = save
                out.append(self._parse_escape())
            else:
                out.append(c)
                self.i += 1
        self.error()

    def _parse_multiline_literal(self):
        self.i += 3
        if self.s[self.i:self.i+2] == "\r\n":
            self.i += 2
        elif self.peek() == "\n":
            self.i += 1
        start = self.i
        while self.i < self.n:
            if self.s[self.i:self.i+3] == "'''":
                val = self.s[start:self.i]
                self.i += 3
                extra = ""
                while self.peek() == "'" and len(extra) < 2:
                    extra += "'"
                    self.i += 1
                return val + extra
            self.i += 1
        self.error()

    def _parse_array(self):
        assert self.peek() == "["
        self.i += 1
        arr = []
        while True:
            self._skip_ws_and_newlines()
            if self.peek() == "]":
                self.i += 1
                return arr
            if self.eof():
                self.error()
            arr.append(self._parse_value())
            self._skip_ws_and_newlines()
            if self.peek() == ",":
                self.i += 1
                continue
            if self.peek() == "]":
                self.i += 1
                return arr
            self.error()

    def _parse_inline_table(self):
        assert self.peek() == "{"
        self.i += 1
        tbl = TomlTable()
        tbl.explicit = True
        while True:
            # TOML 1.0 forbids newlines in inline tables; be lenient-ish but
            # keep behaviour close for common files.
            while self.i < self.n and self.s[self.i] in " \t":
                self.i += 1
            if self.peek() == "}":
                self.i += 1
                return tbl
            if self.eof():
                self.error()
            self._parse_key_value_into(tbl, [])
            while self.i < self.n and self.s[self.i] in " \t":
                self.i += 1
            if self.peek() == ",":
                self.i += 1
                continue
            if self.peek() == "}":
                self.i += 1
                return tbl
            self.error()

def parse_toml(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    parser = _TomlParser(text)
    return parser.parse()

# ---------- Configuration ----------
class Config:
    pass

def load_config(path):
    """Returns (config, error_code) - error_code 0 ok, 1 fatal io, 2 toml parse."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return None, 1
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None, 1
    try:
        root = parse_toml(text)
    except TomlError:
        return None, 2
    except Exception:
        return None, 2
    # Structural validation
    try:
        cfg = validate_config(root)
    except TomlError:
        return None, 2
    return cfg, 0

def validate_config(root):
    if not isinstance(root, dict):
        raise TomlError("root")
    if "clog" not in root:
        raise TomlError("missing clog")
    clog = root["clog"]
    if not isinstance(clog, dict) or isinstance(clog, list):
        raise TomlError("clog not table")
    cfg = Config()
    cfg.repository = None
    cfg.subtitle = None
    cfg.link_style = None
    cfg.output_format = None
    cfg.from_latest_tag = False
    cfg.from_latest_tag_present = False
    cfg.outfile = None
    cfg.infile = None
    cfg.changelog = None
    cfg.git_dir = None
    cfg.has_git_dir = False
    cfg.sections = []  # list of (title, [aliases])

    str_keys = {
        "repository": "repository",
        "subtitle": "subtitle",
        "outfile": "outfile",
        "infile": "infile",
        "changelog": "changelog",
        "git-dir": "git_dir",
    }
    for key, val in clog.items():
        if key in str_keys:
            if not isinstance(val, str):
                raise TomlError("clog %s type" % key)
            setattr(cfg, str_keys[key], val)
            if key == "git-dir":
                cfg.has_git_dir = True
        elif key == "link-style":
            if not isinstance(val, str) or val.lower() not in ("github", "gitlab", "stash", "cgit"):
                raise TomlError("link-style")
            cfg.link_style = val.lower()
        elif key == "output-format":
            if not isinstance(val, str) or val.lower() not in ("markdown", "json"):
                raise TomlError("output-format")
            cfg.output_format = val.lower()
        elif key == "from-latest-tag":
            if not isinstance(val, bool):
                raise TomlError("from-latest-tag")
            cfg.from_latest_tag = val
            cfg.from_latest_tag_present = True
        else:
            # unknown keys are ignored
            pass

    if "sections" in root:
        secs = root["sections"]
        if not isinstance(secs, dict) or isinstance(secs, list):
            raise TomlError("sections")
        for title, aliases in secs.items():
            if not isinstance(aliases, list):
                raise TomlError("sections value")
            for a in aliases:
                if not isinstance(a, str):
                    raise TomlError("sections alias")
            cfg.sections.append((title, list(aliases)))
    return cfg

# ---------- Git access ----------
def _git_env():
    env = dict(os.environ)
    # Prevent the caller's git environment / repo discovery helpers from
    # changing what --git-dir means.
    for k in list(env.keys()):
        if k in ("GIT_DIR", "GIT_WORK_TREE", "GIT_NAMESPACE", "GIT_OBJECT_DIRECTORY",
                 "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_INDEX_FILE", "GIT_COMMON_DIR"):
            del env[k]
    env["GIT_CONFIG_NOSYSTEM"] = env.get("GIT_CONFIG_NOSYSTEM", "0")
    return env

def run_git(git_dir, args, input_data=None):
    cmd = ["git", "--git-dir=" + git_dir] + args
    try:
        r = subprocess.run(cmd, input=input_data, stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, env=_git_env())
        return r.returncode, r.stdout, r.stderr
    except Exception:
        return 1, b"", b""

def get_latest_tag_oid(git_dir):
    # List refs/tags in refname (ascending) order, peel to commits, choose
    # the greatest committer time; first wins on ties.
    rc, out, _ = run_git(git_dir, ["for-each-ref", "--format=%(refname)%00%(objectname)%00%(*objectname)%00%(objecttype)%00%(*objecttype)", "refs/tags"])
    if rc != 0:
        return None
    best_oid = None
    best_time = None
    # Decode preserving bytes-ish via surrogateescape
    text = out.decode("utf-8", "surrogateescape")
    for line in text.splitlines():
        if not line:
            continue
        parts = line.split("\x00")
        if len(parts) < 5:
            continue
        _ref, obj, peeled, objtype, peeled_type = parts[:5]
        target = None
        if peeled:
            if peeled_type != "commit":
                continue
            target = peeled
        else:
            if objtype != "commit":
                continue
            target = obj
        # Get the committer time of the target commit.
        rc2, out2, _ = run_git(git_dir, ["cat-file", "commit", target])
        if rc2 != 0:
            continue
        ctime = _commit_time_from_raw(out2)
        if ctime is None:
            continue
        if best_time is None or ctime > best_time:
            best_time = ctime
            best_oid = target
    return best_oid

def _commit_time_from_raw(raw):
    # raw commit object bytes: headers, blank line, message
    head = raw.split(b"\n\n", 1)[0]
    for line in head.split(b"\n"):
        if line.startswith(b"committer "):
            # "... <email> 123456 +0000"
            try:
                rest = line[10:]
                # last two space-separated fields are ts and tz
                parts = rest.rsplit(b" ", 2)
                return int(parts[-2])
            except Exception:
                return None
    return None

def get_commit_oids(git_dir, spec_args):
    rc, out, _ = run_git(git_dir, ["rev-list"] + spec_args)
    if rc != 0:
        return []
    oids = []
    for line in out.decode("ascii", "ignore").splitlines():
        line = line.strip()
        if line:
            oids.append(line)
    return oids

def get_raw_commits(git_dir, oids):
    if not oids:
        return {}
    inp = ("\n".join(oids) + "\n").encode()
    rc, out, _ = run_git(git_dir, ["cat-file", "--batch"], input_data=inp)
    result = {}
    if rc != 0:
        # fall back to one-by-one
        for oid in oids:
            rc2, out2, _ = run_git(git_dir, ["cat-file", "commit", oid])
            if rc2 == 0:
                result[oid] = out2
        return result
    i = 0
    n = len(out)
    for expected in oids:
        nl = out.find(b"\n", i)
        if nl == -1:
            break
        header = out[i:nl].decode("ascii", "surrogateescape")
        i = nl + 1
        parts = header.split(" ")
        if len(parts) >= 3 and parts[1] == "commit":
            try:
                size = int(parts[2])
            except Exception:
                break
            content = out[i:i+size]
            i += size
            # batch output adds a trailing newline after the contents
            if i < n and out[i:i+1] == b"\n":
                i += 1
            result[parts[0]] = content
        elif len(parts) >= 2 and parts[1] == "missing":
            continue
        else:
            break
    return result

def split_commit_message(raw_bytes):
    parts = raw_bytes.split(b"\n\n", 1)
    if len(parts) == 2:
        return parts[1]
    # No blank line: a commit object without a message, or headers only.
    # If there is no header/message separator, treat the message as empty.
    return b""

def summary_and_body(message_text):
    raw_lines = message_text.split("\n")
    lines = []
    for ln in raw_lines:
        if ln.endswith("\r"):
            ln = ln[:-1]
        lines.append(ln)
    idx = 0
    # skip leading blank lines
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    summary_lines = []
    while idx < len(lines) and lines[idx].strip() != "":
        summary_lines.append(lines[idx].rstrip(" \t\r\f\v"))
        idx += 1
    summary = " ".join(summary_lines)
    if idx < len(lines):
        body_lines = lines[idx+1:]
    else:
        body_lines = []
    return summary, body_lines

# ---------- Commit parsing ----------
SUMMARY_RE = re.compile(r"^([^(:]+)(?:\(([^)]*)\))?:(.*)$", re.DOTALL)
CLOSES_RE = re.compile(r"(?:Closes|Fixes|Resolves) ((?:#(\d+)(?:,\s)?)+)")
BREAKS_RE = re.compile(r"(?:Breaks|Broke) ((?:#(\d+)(?:,\s)?)+)")
BREAKING_RE = re.compile(r"breaking", re.IGNORECASE)

def issue_link_for(issue, repository, link_style):
    if repository is not None and link_style in ("github", "gitlab"):
        return "%s/issues/%s" % (repository, issue)
    return "%s" % issue

def commit_link_for(oid, repository, link_style):
    if repository is None:
        return oid[:8]
    if link_style == "stash":
        return "%s/commits/%s" % (repository, oid)
    if link_style == "cgit":
        return "%s/commit/?id=%s" % (repository, oid)
    # github and gitlab are identical here
    return "%s/commit/%s" % (repository, oid)

class CommitEntry:
    pass

def collect_commits(git_dir, from_val, to_val, cfg, repository, link_style):
    # from_val: None (walk HEAD), a string, or the sentinel False (invalid)
    if from_val is False:
        return []
    if from_val is None:
        oids = get_commit_oids(git_dir, ["HEAD"])
    else:
        rng = "%s..%s" % (from_val, to_val)
        oids = get_commit_oids(git_dir, [rng])
    if not oids:
        return []
    raw_map = get_raw_commits(git_dir, oids)
    entries_by_section = {title: [] for title, _ in cfg.sections}
    for oid in oids:
        raw = raw_map.get(oid)
        if raw is None:
            continue
        msg_bytes = split_commit_message(raw)
        msg = msg_bytes.decode("utf-8", "surrogateescape")
        summary, body_lines = summary_and_body(msg)
        m = SUMMARY_RE.match(summary)
        if not m:
            continue
        typ = m.group(1)
        comp = m.group(2)
        subject = m.group(3)
        if comp == "":
            comp = None
        # find the section: first section (config order) whose aliases match
        matched_title = None
        for title, aliases in cfg.sections:
            if typ in aliases:
                matched_title = title
                break
        if matched_title is None:
            continue
        # closes / breaks from the body, one match of each kind per line
        closes = []
        breaks = []
        for line in body_lines:
            cm = CLOSES_RE.search(line)
            if cm:
                issue = cm.group(2)
                closes.append((issue, issue_link_for(issue, repository, link_style)))
            bm = BREAKS_RE.search(line)
            if bm:
                issue = bm.group(2)
                breaks.append((issue, issue_link_for(issue, repository, link_style)))
            elif BREAKING_RE.search(line):
                issue = ""
                breaks.append((issue, issue_link_for(issue, repository, link_style)))
        e = CommitEntry()
        e.oid = oid
        e.component = comp
        e.subject = subject
        e.commit_link = commit_link_for(oid, repository, link_style)
        e.closes = closes if closes else None
        e.breaks = breaks if breaks else None
        entries_by_section[matched_title].append(e)
    sections = []
    for title, _aliases in cfg.sections:
        commits = entries_by_section.get(title, [])
        if not commits:
            continue
        # Stable sort by component: None first, then the string itself.
        commits_sorted = sorted(commits, key=lambda c: (0, "") if c.component is None else (1, c.component))
        sections.append((title, commits_sorted))
    return sections

# ---------- Output generation ----------
def _issue_segment(kind, issues):
    if not issues:
        return ""
    if len(issues) == 1 and issues[0][1] == "":
        return ""
    parts = ["[#%s](%s)" % (iss, link) for iss, link in issues]
    return ", %s %s" % (kind, ", ".join(parts))

def _commit_parens(c):
    s = "([%s](%s)" % (c.oid[:8], c.commit_link)
    s += _issue_segment("closes", c.closes)
    s += _issue_segment("breaks", c.breaks)
    s += ")"
    return s

def render_markdown(version, subtitle, date_str, sections):
    v = version if version is not None else ""
    s = subtitle if subtitle is not None else ""
    out = []
    out.append('<a name="%s"></a>\n' % v)
    out.append("## %s %s (%s)\n\n" % (v, s, date_str))
    for title, commits in sections:
        out.append("\n#### %s\n\n" % title)
        # group consecutive commits by component (list is component-sorted)
        idx = 0
        while idx < len(commits):
            comp = commits[idx].component
            group = [commits[idx]]
            j = idx + 1
            if comp is not None:
                while j < len(commits) and commits[j].component == comp:
                    group.append(commits[j])
                    j += 1
            if comp is not None and len(group) > 1:
                out.append("* **%s:**\n" % comp)
                for c in group:
                    out.append("  * %s %s\n" % (c.subject, _commit_parens(c)))
            else:
                for c in group:
                    comp_part = ("**%s:**" % comp) if comp is not None else ""
                    out.append("* %s %s %s\n" % (comp_part, c.subject, _commit_parens(c)))
            idx = j if comp is not None else idx + 1
    return "".join(out)

def _json_string(s):
    # JSON string escaping matching serde_json for the common cases.
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif o < 0x20:
            out.append('\\u%04x' % o)
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)

def _rust_debug_string(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20:
            out.append('\\u{%x}' % o)
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)

def _json_issues(issues):
    if issues is None:
        return "null"
    parts = []
    for iss, link in issues:
        parts.append('{"issue":%s,"issue_link":%s}' % (iss, _json_string(link)))
    return "[" + ",".join(parts) + "]"

def render_json(version, subtitle, date_str, sections):
    if version is None:
        version_part = "None"
    else:
        version_part = "Some(%s)" % _rust_debug_string(version)
    subtitle_part = "null" if subtitle is None else subtitle
    header = '{"version":%s,"patch_version":false,"subtitle":%s,"date":"%s"}' % (
        version_part, subtitle_part, date_str)
    if not sections:
        return '{"header":%s,"sections":null}' % header
    sec_parts = []
    for title, commits in sections:
        commit_parts = []
        for c in commits:
            comp_part = "null" if c.component is None else _json_string(c.component)
            closes_part = _json_issues(c.closes)
            # The reference JSON writer (incorrectly) serialises the
            # *closes* list for the breaks field whenever breaks exist.
            if c.breaks is None:
                breaks_part = "null"
            elif c.closes is None:
                breaks_part = "[]"
            else:
                breaks_part = _json_issues(c.closes)
            commit_parts.append(
                '{"component":%s,"subject":%s,"commit_link":%s,"closes":%s,"breaks":%s}' % (
                    comp_part, _json_string(c.subject), _json_string(c.commit_link),
                    closes_part, breaks_part))
        sec_parts.append('{"title":%s,"commits":[%s]}' % (_json_string(title), ",".join(commit_parts)))
    return '{"header":%s,"sections":[%s]}' % (header, ",".join(sec_parts))

# ---------- path resolution ----------
def effective_git_dir(opts):
    if opts.git_dir is not None:
        return opts.git_dir
    cfg_path = opts.config if opts.config is not None else ".clog.toml"
    parent = os.path.dirname(cfg_path)
    if parent:
        # Rust Path::file_name of the parent directory
        trimmed = parent.rstrip("/")
        last = trimmed.rsplit("/", 1)[-1] if trimmed else ""
        if last == ".git":
            return parent
        return os.path.join(parent, ".git")
    return ".git"

# ---------- main ----------
def main_inner(argv):
    try:
        opts = parse_args(argv)
    except ClapExit as e:
        return e.code

    cfg_path = opts.config if opts.config is not None else ".clog.toml"
    cfg, err = load_config(cfg_path)
    if err == 1:
        return fail_red("fatal I/O error with output file")
    if err == 2:
        return fail_red("Failed to parse TOML configuration file")

    # Deterministic panic observed for this (otherwise valid) combination.
    if cfg.has_git_dir and cfg.from_latest_tag:
        return panic_gitdir_from_latest()

    # Version handling.
    if opts.setversion is not None:
        version = opts.setversion
    else:
        if opts.major or opts.minor or opts.patch:
            return fail_red("Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.")
        version = None
    subtitle = opts.subtitle

    git_dir = effective_git_dir(opts)

    # Effective "from".
    if opts.from_ is not None if False else getattr(opts, "from", None) is not None:
        from_val = getattr(opts, "from")
    elif opts.from_latest_tag:
        latest = get_latest_tag_oid(git_dir)
        from_val = latest if latest is not None else False
    elif cfg.from_latest_tag:
        from_val = False
    else:
        from_val = None

    to_val = opts.to if opts.to is not None else "HEAD"

    sections = collect_commits(git_dir, from_val, to_val, cfg, opts.repository, opts.link_style)

    date_str = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d")

    fmt = opts.format if opts.format is not None else "markdown"
    if fmt == "json":
        new_content = render_json(version, subtitle, date_str, sections)
    else:
        new_content = render_markdown(version, subtitle, date_str, sections)

    # Effective infile / outfile.
    eff_outfile = cfg.outfile
    eff_infile = cfg.infile
    if cfg.changelog is not None:
        eff_infile = cfg.changelog
        eff_outfile = cfg.changelog
    if opts.outfile is not None:
        eff_outfile = opts.outfile
    if opts.infile is not None:
        eff_infile = opts.infile
    if opts.changelog is not None:
        eff_infile = opts.changelog
        eff_outfile = opts.changelog

    old_source = eff_infile
    if old_source is None and eff_outfile is not None:
        old_source = eff_outfile

    full_content = new_content
    if old_source is not None:
        try:
            with open(old_source, "rb") as f:
                old_bytes = f.read()
            old_content = old_bytes.decode("utf-8")
        except Exception:
            old_content = ""
        full_content = new_content + "\n\n\n" + old_content

    if eff_outfile is not None:
        try:
            with open(eff_outfile, "wb") as f:
                f.write(full_content.encode("utf-8", "surrogateescape"))
        except OSError:
            return fail_red("fatal I/O error with output file")
    else:
        write_stdout_text(full_content)

    elapsed_ms = int((time.time() - START_TIME) * 1000) if START_TIME else 0
    write_stdout_text("changelog written. (took %d ms)\n" % elapsed_ms)
    return 0

def main():
    # Python uses "from" as a keyword: the OptDef name is "from" and
    # parse_args stores it with setattr, so no source-level conflict arises
    # outside the one guarded expression in main_inner.
    try:
        code = main_inner(sys.argv[1:])
    except ClapExit as e:
        code = e.code
    except BrokenPipeError:
        code = 101
    sys.exit(code)

if __name__ == "__main__":
    import time
    main()
