# ---------- help formatting ----------
def _term_width():
    cols = os.environ.get("COLUMNS")
    if cols is not None:
        try:
            w = int(cols)
            if w > 0:
                return w
            if w == 0:
                return 0
            return 100
        except Exception:
            return 100
    try:
        if sys.stdout.isatty():
            return os.get_terminal_size(sys.stdout.fileno()).columns
    except Exception:
        pass
    return 100

def _wrap_words(text, width):
    if width is None or width <= 0:
        width = 1
    # Split into paragraphs by blank lines first.
    out_lines = []
    paragraphs = text.split("\n\n")
    for para in paragraphs:
        # Preserve explicit single newlines? Help texts have none of importance.
        words = para.split(" ")
        line = ""
        for word in words:
            if word == "":
                continue
            if line == "":
                line = word
            elif len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                out_lines.append(line)
                line = word
        if line != "" or para == "":
            out_lines.append(line)
        # blank line between paragraphs handled by caller / extra entry
        out_lines.append(None)
    if out_lines and out_lines[-1] is None:
        out_lines.pop()
    # Replace paragraph separators (None) with ""
    return ["" if x is None else x for x in out_lines]

