            "\n"
            "If your .git directory is a child of your project directory (most common, such as /myproject/.git)\n"
            "AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only\n"
            "need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you\n"
            "don't need to use both.\n"
            "\n"
            "If using the --config to specify a clog configuration TOML file NOT in the current working directory\n"
            "(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project\n"
            "directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.\n"
        )
        return txt % prog

    # General rendering for other widths, approximating clap's layout.
    display_width = width if width > 0 else 20
    lines = []
    # About line wrapped at the full width.
    lines.extend(_wrap_words("a conventional changelog for the rest of us", display_width))
    lines.append("")
    lines.append("Usage: %s [OPTIONS]" % prog)
    lines.append("")
    lines.append("Options:")
    specs = [(o.spec(), o.help) for o in OPTS]
    specs.append(("-h, --help", "Print help"))
    specs.append(("-V, --version", "Print version"))
    max_spec = max(len(s) for s, _ in specs)
    help_col = 2 + max_spec + 2
    stacked = (30 <= display_width < 65)
    if stacked:
        indent = " " * 10
        help_width = max(display_width - 10, 1)
        for spec, h in specs:
            lines.append("  " + spec)
            if h:
                for hl in _wrap_words(h, help_width):
                    lines.append(indent + hl)
            # clap prints no extra blank line here
    else:
        help_width = max(display_width - help_col, 1)
        for spec, h in specs:
            left = "  " + spec
            if not h:
                lines.append(left + " " * (help_col - len(left)))
                continue
            wrapped = _wrap_words(h, help_width)
            first = True
            for hl in wrapped:
                if first:
                    lines.append(left + " " * (help_col - len(left)) + hl)
                    first = False
                else:
                    lines.append(" " * help_col + hl)
    lines.append("")
    lines.append("")
    for para in _wrap_words(HELP_AFTER, display_width):
        lines.append(para)
    return "\n".join(lines) + "\n"

def print_help():
    write_stdout_text(format_help())

def print_version():
    write_stdout_text(VERSION + "\n")

# ---------- clap-ish error helpers ----------
class ClapExit(Exception):
    def __init__(self, code):
        self.code = code

def _usage_line(suffix):
    return "Usage: %s %s" % (prog_name(), suffix)

def clap_error(message, usage_suffix="[OPTIONS]", extra_lines=None):
    txt = "error: %s\n" % message
    if extra_lines:
        txt += extra_lines
    txt += "\n%s\n\nFor more information, try '--help'.\n" % _usage_line(usage_suffix)
    write_stderr_text(txt)
    raise ClapExit(2)

def err_unexpected_arg(arg_display, seen=None):
    # arg_display like "--repo", "'foo'", "-Z", "'-'"
    tip = None
    usage = "[OPTIONS]"
    extra = ""
    raw_name = None
    if arg_display.startswith("--") and not arg_display.startswith("'-"):
        raw_name = arg_display[2:]
        tip = best_suggestion(raw_name, LONG_CANDIDATES)
    if tip:
        extra = "\n  tip: a similar argument exists: '--%s'\n" % tip
        if tip in ("help", "version"):
            if seen:
                usage = "--%s %s" % (tip, HUGE_USAGE_LIST)
            else:
                usage = "--%s" % tip
        elif tip == "setversion":
            usage = "%s> <--setversion <VER>>" % HUGE_USAGE_LIST
        else:
            usage = HUGE_USAGE_LIST
    clap_error("unexpected argument '%s' found" % arg_display.lstrip("'") if False else ("unexpected argument %s found" % _quoted_arg(arg_display)), usage, extra)

def _quoted_arg(a):
    if len(a) >= 2 and a[0] == "'" and a[-1] == "'":
        return a
    return "'%s'" % a

def err_unexpected_positional(val, seen=None):
    clap_error("unexpected argument '%s' found" % val, "[OPTIONS]")

def err_unexpected_value(val, optdisplay, already_seen=False):
    if already_seen:
        usage = HUGE_USAGE_LIST
    else:
        usage = optdisplay
    txt = "error: unexpected value '%s' for '%s' found; no more were expected\n\n%s\n\nFor more information, try '--help'.\n" % (
        val, optdisplay, _usage_line(usage))
    write_stderr_text(txt)
    raise ClapExit(2)

def err_missing_value(opt):
    txt = "error: a value is required for '%s' but none was supplied\n" % opt.display()
    if opt.possible:
        txt += "  [possible values: %s]\n" % ", ".join(opt.possible)
    txt += "\nFor more information, try '--help'.\n"
    write_stderr_text(txt)
    raise ClapExit(2)

def err_duplicate(opt):
    clap_error("the argument '%s' cannot be used multiple times" % opt.display(), "[OPTIONS]")

def err_invalid_value(val, opt):
    tip = None
    if opt.possible:
        tip = best_suggestion(val, opt.possible)
    txt = "error: invalid value '%s' for '%s'\n" % (val, opt.display())
    if opt.possible:
        txt += "  [possible values: %s]\n" % ", ".join(opt.possible)
    if tip:
        txt += "\n  tip: a similar value exists: '%s'\n" % tip
    txt += "\nFor more information, try '--help'.\n"
    write_stderr_text(txt)
    raise ClapExit(2)

# conflicts
CONFLICT_PAIRS = [
    ("from", "from_latest_tag"),
    ("outfile", "changelog"),
    ("infile", "changelog"),
]
NAME_TO_OPT = {o.name: o for o in OPTS}

def check_conflicts(order, values):
    # order: list of opt names in first-occurrence order
    present = set(order)
    conflicting = {}
    for a, b in CONFLICT_PAIRS:
        if a in present and b in present:
            conflicting.setdefault(a, []).append(b)
            conflicting.setdefault(b, []).append(a)
    if not conflicting:
        return
    main_name = None
    for name in order:
        if name in conflicting:
            main_name = name
            break
    main = NAME_TO_OPT[main_name]
    secs = [n for n in order if n in conflicting.get(main_name, [])]
    # Build message
    if len(secs) == 1:
        msg = "error: the argument '%s' cannot be used with '%s'\n" % (main.display(), NAME_TO_OPT[secs[0]].display())
    else:
        msg = "error: the argument '%s' cannot be used with:\n" % main.display()
        for s in secs:
            msg += "  %s\n" % NAME_TO_OPT[s].display()
    usage_args = [NAME_TO_OPT[n].display() for n in order if n not in secs]
    usage = " ".join(usage_args)
    msg += "\n%s\n\nFor more information, try '--help'.\n" % _usage_line(usage)
    write_stderr_text(msg)
    raise ClapExit(2)

# ---------- Argument parsing ----------
class Parsed:
    pass

def _is_known_option_token(tok):
    """Whether tok looks like a known option (for missing-value decisions)."""
    if tok == "-" or tok == "--":
        return False
    if tok.startswith("--"):
        name = tok[2:].split("=", 1)[0]
        return name in BY_LONG or name in ("help", "version")
    if tok.startswith("-") and len(tok) > 1:
        ch = tok[1]
        return ch in BY_SHORT or ch in ("h", "V")
    return False

def _unknown_from_token(tok, seen):
    """Raise the error clap raises for an unknown option token."""
    if tok.startswith("--"):
        name = tok[2:].split("=", 1)[0]
        err_unexpected_arg("--" + name, seen)
    else:
        ch = tok[1] if len(tok) > 1 else ""
        err_unexpected_arg("-" + ch, seen)

def parse_args(argv):
    p = Parsed()
    seen = {}
    order = []
    # defaults
    for o in OPTS:
        if o.is_flag:
            setattr(p, o.name, False)
        else:
            setattr(p, o.name, o.default)
    p._order = order
    p._seen = seen

    def store(opt, value):
        # value presence already established by caller for option-values;
        # duplicate is reported before enum validation.
        if opt.name in seen:
            err_duplicate(opt)
        if opt.possible is not None:
            if value == "":
                err_missing_value(opt)
            if value not in opt.possible:
                err_invalid_value(value, opt)
        seen[opt.name] = True
        order.append(opt.name)
        setattr(p, opt.name, value if not opt.is_flag else True)

    def store_flag(opt):
        if opt.name in seen:
            err_duplicate(opt)
        seen[opt.name] = True
        order.append(opt.name)
        setattr(p, opt.name, True)

    def take_value(opt, idx, attached):
        # Returns (value, new_idx). attached is None if not attached.
        if attached is not None:
            return attached, idx
        # need next token
        if idx + 1 >= len(argv):
            err_missing_value(opt)
        nxt = argv[idx + 1]
        if nxt == "-":
            return nxt, idx + 1
        if nxt == "--":
            # If tokens follow --, clap surfaces the following positional first.
            if idx + 2 < len(argv):
                err_unexpected_positional(argv[idx + 2], seen)
            err_missing_value(opt)
        if len(nxt) > 1 and nxt.startswith("-"):
            if _is_known_option_token(nxt):
                err_missing_value(opt)
            else:
                _unknown_from_token(nxt, seen)
        return nxt, idx + 1

    i = 0
    only_positional = False
    while i < len(argv):
        tok = argv[i]
        if only_positional:
            err_unexpected_positional(tok, seen)
        if tok == "--":
            only_positional = True
            i += 1
            continue
        if tok.startswith("--") and len(tok) > 2:
            body = tok[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                has_eq = True
            else:
                name, val = body, None
                has_eq = False
            if name in ("help", "version"):
                if has_eq:
                    err_unexpected_value(val, "--" + name, False)
                if name == "help":
                    print_help()
                else:
                    print_version()
                raise ClapExit(0)
            opt = BY_LONG.get(name)
            if opt is None:
                err_unexpected_arg("--" + name, seen)
            if opt.is_flag:
                if has_eq:
                    err_unexpected_value(val, opt.display(), opt.name in seen)
                store_flag(opt)
                i += 1
                continue
            else:
                if has_eq:
                    value = val
                    # missing check for enum empties comes in store()
                    store(opt, value)
                    i += 1
                    continue
                else:
                    value, i = take_value(opt, i, None)
                    store(opt, value)
                    i += 1
                    continue
        elif tok.startswith("-") and len(tok) > 1:
            if tok == "-":
                err_unexpected_positional("-", seen)
            # short cluster
            j = 1
            consumed_next = False
            while j < len(tok):
                ch = tok[j]
                if ch == "h":
                    print_help()
                    raise ClapExit(0)
                if ch == "V":
                    print_version()
                    raise ClapExit(0)
                opt = BY_SHORT.get(ch)
                if opt is None:
                    err_unexpected_arg("-" + ch, seen)
                if opt.is_flag:
                    store_flag(opt)
                    j += 1
                    continue
                else:
                    rest = tok[j + 1:]
                    if rest.startswith("="):
                        value = rest[1:]
                        store(opt, value)
                    elif rest != "":
                        value = rest
                        store(opt, value)
                    else:
                        value, ni = take_value(opt, i, None)
                        if ni != i:
                            consumed_next = True
                        store(opt, value)
                    break
            i += 2 if consumed_next else 1
            continue
        else:
            err_unexpected_positional(tok, seen)
    # end while
    check_conflicts(order, p)
    return p

# ---------- TOML parsing ----------
class TomlError(Exception):
    pass

class RawScalar:
    def __init__(self, text):
        self.text = text
    def __repr__(self):
        return "RawScalar(%r)" % self.text

class TomlTable(dict):
    def __init__(self):
        super().__init__()
        self.explicit = False
        self.dotted_created = False

class _TomlParser:
    def __init__(self, text):
        self.s = text
        self.i = 0
        self.n = len(text)
        self.root = TomlTable()
        self.current = self.root
        self.current_path = []

    def error(self):
        raise TomlError("toml parse error at %d" % self.i)

    def peek(self):
        return self.s[self.i] if self.i < self.n else ""

    def eof(self):
        return self.i >= self.n

    def _skip_ws(self, allow_newline=False):
        while self.i < self.n:
            c = self.s[self.i]
            if c in " \t":
                self.i += 1
            elif allow_newline and c in "\r\n":
                self.i += 1
            elif c == "#":
                # comment to end of line
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                if allow_newline:
                    continue
                else:
                    break
            else:
                break

    def _skip_ws_and_newlines(self):
        while True:
            start = self.i
            while self.i < self.n and self.s[self.i] in " \t\r\n":
                self.i += 1
            if self.i < self.n and self.s[self.i] == "#":
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                continue
            if self.i == start:
                break

    def parse(self):
        while True:
            self._skip_ws_and_newlines()
            if self.eof():
                break
            c = self.peek()
            if c == "[":
                self._parse_header()
            else:
                self._parse_key_value_into(self.current, self.current_path)
            # after a statement, only comment / newline / EOF may follow
            self._skip_ws(False)
            if self.eof():
                break
            c = self.peek()
            if c == "#":
                while self.i < self.n and self.s[self.i] not in "\r\n":
                    self.i += 1
                continue
            if c in "\r\n":
                continue
            self.error()
        return self.root

    def _parse_header(self):
        # consume '['
        self.i += 1
        is_array = False
        if self.peek() == "[":
            is_array = True
            self.i += 1
        self._skip_ws(False)
        keys = self._parse_key_path()
        self._skip_ws(False)
        if is_array:
            if self.s[self.i:self.i+2] != "]]":
                self.error()
            self.i += 2
        else:
            if self.peek() != "]":
                self.error()
            self.i += 1
        # navigate
        node = self.root
        for idx, key in enumerate(keys):
            last = (idx == len(keys) - 1)
            if last and is_array:
                existing = node.get(key)
                if existing is None:
                    lst = []
                    node[key] = lst
                    tbl = TomlTable()
                    tbl.explicit = True
                    lst.append(tbl)
                    node = tbl
                elif isinstance(existing, list):
                    tbl = TomlTable()
                    tbl.explicit = True
                    existing.append(tbl)
                    node = tbl
                else:
                    self.error()
            elif last:
                existing = node.get(key)
                if existing is None:
                    tbl = TomlTable()
                    tbl.explicit = True
                    node[key] = tbl
                    node = tbl
                elif isinstance(existing, TomlTable):
                    if existing.explicit:
                        self.error()
                    existing.explicit = True
                    node = existing
                else:
                    self.error()
            else:
                existing = node.get(key)
                if existing is None:
                    tbl = TomlTable()
                    node[key] = tbl
                    node = tbl
                elif isinstance(existing, TomlTable):
                    node = existing
                elif isinstance(existing, list) and existing and isinstance(existing[-1], TomlTable):
                    node = existing[-1]
                else:
                    self.error()
        self.current = node
        self.current_path = list(keys)

    def _parse_key_path(self):
        keys = []
        while True:
            self._skip_ws(False)
            keys.append(self._parse_one_key())
            self._skip_ws(False)
            if self.peek() == ".":
                self.i += 1
                continue
            break
        return keys

    def _parse_one_key(self):
        c = self.peek()
        if c == '"':
            return self._parse_basic_string()
        if c == "'":
            return self._parse_literal_string()
        start = self.i
        while self.i < self.n and (self.s[self.i].isalnum() or self.s[self.i] in "_-"):
            self.i += 1
        if self.i == start:
            self.error()
        return self.s[start:self.i]

    def _parse_key_value_into(self, table, base_path):
        keys = self._parse_key_path()
        self._skip_ws(False)
        if self.peek() != "=":
            self.error()
        self.i += 1
        self._skip_ws(False)
        value = self._parse_value()
        # assign traversing dotted keys
        node = table
        full_path = list(base_path) + keys
        for key in keys[:-1]:
            existing = node.get(key)
            if existing is None:
                tbl = TomlTable()
                tbl.dotted_created = True
                node[key] = tbl
                node = tbl
            elif isinstance(existing, TomlTable):
                node = existing
            else:
                self.error()
        last = keys[-1]
        if last in node:
            # Duplicate keys are an error in general, except directly under
            # the top-level [sections] table, where the last value wins
            # (serde map insertion behaviour).
            if base_path == ["sections"] and len(keys) == 1:
                node[last] = value
                return
            self.error()
        node[last] = value

    def _parse_value(self):
        c = self.peek()
        if c == '"':
            if self.s[self.i:self.i+3] == '"""':
                return self._parse_multiline_basic()
            return self._parse_basic_string()
        if c == "'":
            if self.s[self.i:self.i+3] == "'''":
                return self._parse_multiline_literal()
            return self._parse_literal_string()
        if c == "[":
            return self._parse_array()
        if c == "{":
            return self._parse_inline_table()
        # bare token: bool / number / datetime
        start = self.i
        while self.i < self.n and self.s[self.i] not in " \t\r\n,]}#":
            self.i += 1
        tok = self.s[start:self.i]
        if tok == "":
            self.error()
        if tok == "true":
            return True
        if tok == "false":
            return False
        return RawScalar(tok)

    def _parse_basic_string(self):
        assert self.peek() == '"'
        self.i += 1
        out = []
        while self.i < self.n:
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return "".join(out)
            if c in "\r\n":
                self.error()
            if c == "\\":
                out.append(self._parse_escape())
            else:
                out.append(c)
                self.i += 1
        self.error()

    def _parse_escape(self):
        # at backslash
        self.i += 1
        if self.i >= self.n:
            self.error()
        c = self.s[self.i]
        self.i += 1
        mapping = {'b': '\b', 'e': '\x1b', 't': '\t', 'n': '\n', 'f': '\f', 'r': '\r', '"': '"', '\\': '\\'}
        if c in mapping:
            return mapping[c]
        if c == 'u':
            if self.i + 4 > self.n:
                self.error()
            try:
                cp = int(self.s[self.i:self.i+4], 16)
            except Exception:
                self.error()
            self.i += 4
            return chr(cp)
        if c == 'U':
            if self.i + 8 > self.n:
                self.error()
            try:
                cp = int(self.s[self.i:self.i+8], 16)
            except Exception:
                self.error()
            self.i += 8
            return chr(cp)
        self.error()

    def _parse_literal_string(self):
        assert self.peek() == "'"
        self.i += 1
        start = self.i
        while self.i < self.n:
            c = self.s[self.i]
            if c == "'":
                val = self.s[start:self.i]
                self.i += 1
                return val
            if c in "\r\n":
                self.error()
            self.i += 1
        self.error()

    def _parse_multiline_basic(self):
        self.i += 3
        # first newline trimmed
        if self.s[self.i:self.i+2] == "\r\n":
            self.i += 2
        elif self.peek() == "\n":
            self.i += 1
        out = []
        while self.i < self.n:
            if self.s[self.i:self.i+3] == '"""':
                self.i += 3
                # up to two extra quotes are part of the string per TOML
                extra = ""
                while self.peek() == '"' and len(extra) < 2:
                    extra += '"'
                    self.i += 1
                return "".join(out) + extra
            c = self.s[self.i]
            if c == "\\":
                # line-ending backslash?
                save = self.i
                self.i += 1
                j = self.i
                while j < self.n and self.s[j] in " \t":
                    j += 1
                if j < self.n and self.s[j] in "\r\n":
                    # skip newline and following whitespace/newlines
                    self.i = j
                    while self.i < self.n and self.s[self.i] in " \t\r\n":
                        self.i += 1
                    continue
                self.i = save
                out.append(self._parse_escape())
            else:
                out.append(c)
                self.i += 1
        self.error()

    def _parse_multiline_literal(self):
        self.i += 3
        if self.s[self.i:self.i+2] == "\r\n":
            self.i += 2
        elif self.peek() == "\n":
            self.i += 1
        start = self.i
        while self.i < self.n:
            if self.s[self.i:self.i+3] == "'''":
                val = self.s[start:self.i]
                self.i += 3
                extra = ""
                while self.peek() == "'" and len(extra) < 2:
                    extra += "'"
                    self.i += 1
                return val + extra
            self.i += 1
        self.error()

    def _parse_array(self):
        assert self.peek() == "["
        self.i += 1
        arr = []
        while True:
            self._skip_ws_and_newlines()
            if self.peek() == "]":
                self.i += 1
                return arr
            if self.eof():
                self.error()
            arr.append(self._parse_value())
            self._skip_ws_and_newlines()
            if self.peek() == ",":
                self.i += 1
                continue
            if self.peek() == "]":
                self.i += 1
                return arr
            self.error()

    def _parse_inline_table(self):
        assert self.peek() == "{"
        self.i += 1
        tbl = TomlTable()
        tbl.explicit = True
        while True:
            # TOML 1.0 forbids newlines in inline tables; be lenient-ish but
            # keep behaviour close for common files.
            while self.i < self.n and self.s[self.i] in " \t":
                self.i += 1
            if self.peek() == "}":
                self.i += 1
                return tbl
            if self.eof():
                self.error()
            self._parse_key_value_into(tbl, [])
            while self.i < self.n and self.s[self.i] in " \t":
                self.i += 1
            if self.peek() == ",":
                self.i += 1
                continue
            if self.peek() == "}":
                self.i += 1
                return tbl
            self.error()

def parse_toml(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    parser = _TomlParser(text)
    return parser.parse()

# ---------- Configuration ----------
class Config:
    pass

def load_config(path):
    """Returns (config, error_code) - error_code 0 ok, 1 fatal io, 2 toml parse."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return None, 1
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None, 1
    try:
        root = parse_toml(text)
    except TomlError:
        return None, 2
    except Exception:
        return None, 2
    # Structural validation
    try:
        cfg = validate_config(root)
    except TomlError:
        return None, 2
    return cfg, 0

def validate_config(root):
    if not isinstance(root, dict):
        raise TomlError("root")
    if "clog" not in root:
        raise TomlError("missing clog")
    clog = root["clog"]
    if not isinstance(clog, dict) or isinstance(clog, list):
        raise TomlError("clog not table")
    cfg = Config()
    cfg.repository = None
    cfg.subtitle = None
    cfg.link_style = None
    cfg.output_format = None
    cfg.from_latest_tag = False
    cfg.from_latest_tag_present = False
    cfg.outfile = None
    cfg.infile = None
    cfg.changelog = None
    cfg.git_dir = None
    cfg.has_git_dir = False
    cfg.sections = []  # list of (title, [aliases])

    str_keys = {
        "repository": "repository",
        "subtitle": "subtitle",
        "outfile": "outfile",
        "infile": "infile",
        "changelog": "changelog",
        "git-dir": "git_dir",
    }
    for key, val in clog.items():
        if key in str_keys:
            if not isinstance(val, str):
                raise TomlError("clog %s type" % key)
            setattr(cfg, str_keys[key], val)
            if key == "git-dir":
                cfg.has_git_dir = True
        elif key == "link-style":
            if not isinstance(val, str) or val.lower() not in ("github", "gitlab", "stash", "cgit"):
                raise TomlError("link-style")
            cfg.link_style = val.lower()
        elif key == "output-format":
            if not isinstance(val, str) or val.lower() not in ("markdown", "json"):
                raise TomlError("output-format")
            cfg.output_format = val.lower()
        elif key == "from-latest-tag":
            if not isinstance(val, bool):
                raise TomlError("from-latest-tag")
            cfg.from_latest_tag = val
            cfg.from_latest_tag_present = True
        else:
            # unknown keys are ignored
            pass

    if "sections" in root:
        secs = root["sections"]
        if not isinstance(secs, dict) or isinstance(secs, list):
            raise TomlError("sections")
        for title, aliases in secs.items():
            if not isinstance(aliases, list):
                raise TomlError("sections value")
            for a in aliases:
                if not isinstance(a, str):
                    raise TomlError("sections alias")
            cfg.sections.append((title, list(aliases)))
    return cfg

# ---------- Git access ----------
def _git_env():
    env = dict(os.environ)
    # Prevent the caller's git environment / repo discovery helpers from
    # changing what --git-dir means.
    for k in list(env.keys()):
        if k in ("GIT_DIR", "GIT_WORK_TREE", "GIT_NAMESPACE", "GIT_OBJECT_DIRECTORY",
                 "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_INDEX_FILE", "GIT_COMMON_DIR"):
            del env[k]
    env["GIT_CONFIG_NOSYSTEM"] = env.get("GIT_CONFIG_NOSYSTEM", "0")
    return env

def run_git(git_dir, args, input_data=None):
    cmd = ["git", "--git-dir=" + git_dir] + args
    try:
        r = subprocess.run(cmd, input=input_data, stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, env=_git_env())
        return r.returncode, r.stdout, r.stderr
    except Exception:
        return 1, b"", b""

def get_latest_tag_oid(git_dir):
    # List refs/tags in refname (ascending) order, peel to commits, choose
    # the greatest committer time; first wins on ties.
    rc, out, _ = run_git(git_dir, ["for-each-ref", "--format=%(refname)%00%(objectname)%00%(*objectname)%00%(objecttype)%00%(*objecttype)", "refs/tags"])
    if rc != 0:
        return None
    best_oid = None
    best_time = None
    # Decode preserving bytes-ish via surrogateescape
    text = out.decode("utf-8", "surrogateescape")
    for line in text.splitlines():
        if not line:
            continue
        parts = line.split("\x00")
        if len(parts) < 5:
            continue
        _ref, obj, peeled, objtype, peeled_type = parts[:5]
        target = None
        if peeled:
            if peeled_type != "commit":
                continue
            target = peeled
        else:
            if objtype != "commit":
                continue
            target = obj
        # Get the committer time of the target commit.
        rc2, out2, _ = run_git(git_dir, ["cat-file", "commit", target])
        if rc2 != 0:
            continue
        ctime = _commit_time_from_raw(out2)
        if ctime is None:
            continue
        if best_time is None or ctime > best_time:
            best_time = ctime
            best_oid = target
    return best_oid

def _commit_time_from_raw(raw):
    # raw commit object bytes: headers, blank line, message
    head = raw.split(b"\n\n", 1)[0]
    for line in head.split(b"\n"):
        if line.startswith(b"committer "):
            # "... <email> 123456 +0000"
            try:
                rest = line[10:]
                # last two space-separated fields are ts and tz
                parts = rest.rsplit(b" ", 2)
                return int(parts[-2])
            except Exception:
                return None
    return None

def get_commit_oids(git_dir, spec_args):
    rc, out, _ = run_git(git_dir, ["rev-list"] + spec_args)
    if rc != 0:
        return []
    oids = []
    for line in out.decode("ascii", "ignore").splitlines():
        line = line.strip()
        if line:
            oids.append(line)
    return oids

def get_raw_commits(git_dir, oids):
    if not oids:
        return {}
    inp = ("\n".join(oids) + "\n").encode()
    rc, out, _ = run_git(git_dir, ["cat-file", "--batch"], input_data=inp)
    result = {}
    if rc != 0:
        # fall back to one-by-one
        for oid in oids:
            rc2, out2, _ = run_git(git_dir, ["cat-file", "commit", oid])
            if rc2 == 0:
                result[oid] = out2
        return result
    i = 0
    n = len(out)
    for expected in oids:
        nl = out.find(b"\n", i)
        if nl == -1:
            break
        header = out[i:nl].decode("ascii", "surrogateescape")
        i = nl + 1
        parts = header.split(" ")
        if len(parts) >= 3 and parts[1] == "commit":
            try:
                size = int(parts[2])
            except Exception:
                break
            content = out[i:i+size]
            i += size
            # batch output adds a trailing newline after the contents
            if i < n and out[i:i+1] == b"\n":
                i += 1
            result[parts[0]] = content
        elif len(parts) >= 2 and parts[1] == "missing":
            continue
        else:
            break
    return result

def split_commit_message(raw_bytes):
    parts = raw_bytes.split(b"\n\n", 1)
    if len(parts) == 2:
        return parts[1]
    # No blank line: a commit object without a message, or headers only.
    # If there is no header/message separator, treat the message as empty.
    return b""

def summary_and_body(message_text):
    raw_lines = message_text.split("\n")
    lines = []
    for ln in raw_lines:
        if ln.endswith("\r"):
            ln = ln[:-1]
        lines.append(ln)
    idx = 0
    # skip leading blank lines
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    summary_lines = []
    while idx < len(lines) and lines[idx].strip() != "":
        summary_lines.append(lines[idx].rstrip(" \t\r\f\v"))
        idx += 1
    summary = " ".join(summary_lines)
    if idx < len(lines):
        body_lines = lines[idx+1:]
    else:
        body_lines = []
    return summary, body_lines

# ---------- Commit parsing ----------
SUMMARY_RE = re.compile(r"^([^(:]+)(?:\(([^)]*)\))?:(.*)$", re.DOTALL)
CLOSES_RE = re.compile(r"(?:Closes|Fixes|Resolves) ((?:#(\d+)(?:,\s)?)+)")
BREAKS_RE = re.compile(r"(?:Breaks|Broke) ((?:#(\d+)(?:,\s)?)+)")
BREAKING_RE = re.compile(r"breaking", re.IGNORECASE)

def issue_link_for(issue, repository, link_style):
    if repository is not None and link_style in ("github", "gitlab"):
        return "%s/issues/%s" % (repository, issue)
    return "%s" % issue

def commit_link_for(oid, repository, link_style):
    if repository is None:
        return oid[:8]
    if link_style == "stash":
        return "%s/commits/%s" % (repository, oid)
    if link_style == "cgit":
        return "%s/commit/?id=%s" % (repository, oid)
    # github and gitlab are identical here
    return "%s/commit/%s" % (repository, oid)

class CommitEntry:
    pass

def collect_commits(git_dir, from_val, to_val, cfg, repository, link_style):
    # from_val: None (walk HEAD), a string, or the sentinel False (invalid)
    if from_val is False:
        return []
    if from_val is None:
        oids = get_commit_oids(git_dir, ["HEAD"])
    else:
        rng = "%s..%s" % (from_val, to_val)
        oids = get_commit_oids(git_dir, [rng])
    if not oids:
        return []
    raw_map = get_raw_commits(git_dir, oids)
    entries_by_section = {title: [] for title, _ in cfg.sections}
    for oid in oids:
        raw = raw_map.get(oid)
        if raw is None:
            continue
        msg_bytes = split_commit_message(raw)
        msg = msg_bytes.decode("utf-8", "surrogateescape")
        summary, body_lines = summary_and_body(msg)
        m = SUMMARY_RE.match(summary)
        if not m:
            continue
        typ = m.group(1)
        comp = m.group(2)
        subject = m.group(3)
        if comp == "":
            comp = None
        # find the section: first section (config order) whose aliases match
        matched_title = None
        for title, aliases in cfg.sections:
            if typ in aliases:
                matched_title = title
                break
        if matched_title is None:
            continue
        # closes / breaks from the body, one match of each kind per line
        closes = []
        breaks = []
        for line in body_lines:
            cm = CLOSES_RE.search(line)
            if cm:
                issue = cm.group(2)
                closes.append((issue, issue_link_for(issue, repository, link_style)))
            bm = BREAKS_RE.search(line)
            if bm:
                issue = bm.group(2)
                breaks.append((issue, issue_link_for(issue, repository, link_style)))
            elif BREAKING_RE.search(line):
                issue = ""
                breaks.append((issue, issue_link_for(issue, repository, link_style)))
        e = CommitEntry()
        e.oid = oid
        e.component = comp
        e.subject = subject
        e.commit_link = commit_link_for(oid, repository, link_style)
        e.closes = closes if closes else None
        e.breaks = breaks if breaks else None
        entries_by_section[matched_title].append(e)
    sections = []
    for title, _aliases in cfg.sections:
        commits = entries_by_section.get(title, [])
        if not commits:
            continue
        # Stable sort by component: None first, then the string itself.
        commits_sorted = sorted(commits, key=lambda c: (0, "") if c.component is None else (1, c.component))
        sections.append((title, commits_sorted))
    return sections

# ---------- Output generation ----------
def _issue_segment(kind, issues):
    if not issues:
        return ""
    if len(issues) == 1 and issues[0][1] == "":
        return ""
    parts = ["[#%s](%s)" % (iss, link) for iss, link in issues]
    return ", %s %s" % (kind, ", ".join(parts))

def _commit_parens(c):
    s = "([%s](%s)" % (c.oid[:8], c.commit_link)
    s += _issue_segment("closes", c.closes)
    s += _issue_segment("breaks", c.breaks)
    s += ")"
    return s

def render_markdown(version, subtitle, date_str, sections):
    v = version if version is not None else ""
    s = subtitle if subtitle is not None else ""
    out = []
    out.append('<a name="%s"></a>\n' % v)
    out.append("## %s %s (%s)\n\n" % (v, s, date_str))
    for title, commits in sections:
        out.append("\n#### %s\n\n" % title)
        # group consecutive commits by component (list is component-sorted)
        idx = 0
        while idx < len(commits):
            comp = commits[idx].component
            group = [commits[idx]]
            j = idx + 1
            if comp is not None:
                while j < len(commits) and commits[j].component == comp:
                    group.append(commits[j])
                    j += 1
            if comp is not None and len(group) > 1:
                out.append("* **%s:**\n" % comp)
                for c in group:
                    out.append("  * %s %s\n" % (c.subject, _commit_parens(c)))
            else:
                for c in group:
                    comp_part = ("**%s:**" % comp) if comp is not None else ""
                    out.append("* %s %s %s\n" % (comp_part, c.subject, _commit_parens(c)))
            idx = j if comp is not None else idx + 1
    return "".join(out)

def _json_string(s):
    # JSON string escaping matching serde_json for the common cases.
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif o < 0x20:
            out.append('\\u%04x' % o)
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)

def _rust_debug_string(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
