    if version is None:
        version_part = "None"
    else:
        version_part = "Some(%s)" % _rust_debug_string(version)
    subtitle_part = "null" if subtitle is None else subtitle
    header = '{"version":%s,"patch_version":false,"subtitle":%s,"date":"%s"}' % (
        version_part, subtitle_part, date_str)
    if not sections:
        return '{"header":%s,"sections":null}' % header
    sec_parts = []
    for title, commits in sections:
        commit_parts = []
        for c in commits:
            comp_part = "null" if c.component is None else _json_string(c.component)
            closes_part = _json_issues(c.closes)
            # The reference JSON writer (incorrectly) serialises the
            # *closes* list for the breaks field whenever breaks exist.
            if c.breaks is None:
                breaks_part = "null"
            elif c.closes is None:
                breaks_part = "[]"
            else:
                breaks_part = _json_issues(c.closes)
            commit_parts.append(
                '{"component":%s,"subject":%s,"commit_link":%s,"closes":%s,"breaks":%s}' % (
                    comp_part, _json_string(c.subject), _json_string(c.commit_link),
                    closes_part, breaks_part))
        sec_parts.append('{"title":%s,"commits":[%s]}' % (_json_string(title), ",".join(commit_parts)))
    return '{"header":%s,"sections":[%s]}' % (header, ",".join(sec_parts))

# ---------- path resolution ----------
def effective_git_dir(opts):
    if opts.git_dir is not None:
        return opts.git_dir
    cfg_path = opts.config if opts.config is not None else ".clog.toml"
    parent = os.path.dirname(cfg_path)
    if parent:
        # Rust Path::file_name of the parent directory
        trimmed = parent.rstrip("/")
        last = trimmed.rsplit("/", 1)[-1] if trimmed else ""
        if last == ".git":
            return parent
        return os.path.join(parent, ".git")
    return ".git"

