        opts = parse_args(argv)
    except ClapExit as e:
        return e.code

    cfg_path = opts.config if opts.config is not None else ".clog.toml"
    cfg, err = load_config(cfg_path)
    if err == 1:
        return fail_red("fatal I/O error with output file")
    if err == 2:
        return fail_red("Failed to parse TOML configuration file")

    # Deterministic panic observed for this (otherwise valid) combination.
    if cfg.has_git_dir and cfg.from_latest_tag:
        return panic_gitdir_from_latest()

    # Version handling.
    if opts.setversion is not None:
        version = opts.setversion
    else:
        if opts.major or opts.minor or opts.patch:
            return fail_red("Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.")
        version = None
    subtitle = opts.subtitle

    git_dir = effective_git_dir(opts)

