    view = memoryview(b)
    while len(view) > 0:
        try:
            n = os.write(fd, view)
        except InterruptedError:
            continue
        if n <= 0:
            break
        view = view[n:]

def _write_stdout_bytes(b, kind="message"):
    try:
        _write_fd(1, b)
    except OSError as e:
        if kind == "ignore":
            return
        if kind == "content":
            raise
        # Rust's println! panics when writing the final status line fails.
        try:
